export type replyIndexResponse200 = {
  data: ReplyIndex200;
  status: 200;
};

export type replyIndexResponse400 = {
  data: BadRequestResponse;
  status: 400;
};

export type replyIndexResponse404 = {
  data: NotFoundResponse;
  status: 404;
};

export type replyIndexResponse422 = {
  data: UnprocessableContentResponse;
  status: 422;
};

export type replyIndexResponseSuccess = replyIndexResponse200 & {
  headers: Headers;
};
export type replyIndexResponseError = (
  replyIndexResponse400 | replyIndexResponse404 | replyIndexResponse422
) & {
  headers: Headers;
};

export type replyIndexResponse = replyIndexResponseSuccess | replyIndexResponseError;

export const getReplyIndexUrl = (postId: string, params?: ReplyIndexParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/posts/${postId}/replies?${stringifiedParams}`
    : `/api/posts/${postId}/replies`;
};

/**
 * The top level, or the direct replies to parent_id, which read oldest first
 * @summary List one level of a post's replies
 */
export const replyIndex = async (
  postId: string,
  params?: ReplyIndexParams,
  options?: Parameters<typeof customFetch>[1],
): Promise<replyIndexResponse> => {
  return customFetch<replyIndexResponse>(getReplyIndexUrl(postId, params), {
    ...options,
    method: 'GET',
  });
};

